namespace TerraformGenerator.Domain;

// The README of the generated folder: written for someone who has never used Terraform or Bicep.
public static class Readme
{
    public static string Write(SketchModel model)
    {
        if (!model.IsAzure)
        {
            return Cloud(model);
        }

        var name = $"{model.Settings.Name}-{model.Settings.Environment}";
        var lines = new List<string>
        {
            $"# {model.Settings.Name} ({model.Settings.Environment}) on Azure",
            "",
            "Generated by Terraform Generator from your drawing (`sketch.json`). To change the design, open the drawing in Terraform Generator, change it, download again and replace these files (keep `terraform.tfvars` and `backend.hcl`).",
            "",
            "## What you need (once)",
            "",
            "- An Azure subscription where you are **Owner** (the code gives the apps their roles, which needs that permission).",
            "- PowerShell 7 (`winget install Microsoft.PowerShell`) and the Azure CLI (`winget install Microsoft.AzureCLI`).",
        };
        if (model.Terraform)
        {
            lines.Add("- Terraform 1.6 or later (`winget install Hashicorp.Terraform`).");
        }

        lines.Add("");
        lines.Add("`check-prereqs.ps1` checks all of this, signs you in to Azure and registers the Azure services the design uses.");
        lines.Add("");

        if (model.Terraform)
        {
            lines.Add("## Create or update everything");
            lines.Add("");
            lines.Add("Open PowerShell 7 in this folder and run:");
            lines.Add("");
            lines.Add("```powershell");
            lines.Add("./deploy.ps1");
            lines.Add("```");
            lines.Add("");
            lines.Add("It checks the tools, signs you in, writes `terraform.tfvars` for your subscription"
                + (model.RemoteState ? ", creates the storage for the Terraform state (first time only)" : "")
                + ", shows the plan (what will be created, changed or deleted) and asks you to type `yes` before it changes anything. Run it again after every change; it only changes what differs.");
            lines.Add("");
            lines.Add(model.RemoteState
                ? "Terraform keeps a record of what it created (the *state*) in the storage account that `bootstrap-state.ps1` creates, with versioning and 30 days of soft delete. Never delete that resource group."
                : "Terraform keeps a record of what it created (the *state*) in `terraform.tfstate` in this folder. Do not lose it: without it Terraform no longer knows what it created.");
            lines.Add("");
        }

        if (model.Bicep)
        {
            lines.Add(model.Terraform ? "## Or with Bicep" : "## Create or update everything (Bicep)");
            lines.Add("");
            lines.Add("The `bicep` folder has the same design in Bicep, Azure's own language. Bicep needs no state file: Azure itself remembers what each deployment created.");
            lines.Add("");
            lines.Add("```powershell");
            lines.Add("./deploy-bicep.ps1");
            lines.Add("```");
            lines.Add("");
            lines.Add("It creates the resource group, shows a preview (what-if) and asks you to type `yes`.");
            if (model.Terraform)
            {
                lines.Add("Use one or the other for an environment, never both: each would try to manage the same resources.");
            }

            lines.Add("");
        }

        var after = AfterFirstDeploy(model);
        if (after.Count > 0)
        {
            lines.Add("## After the first deploy");
            lines.Add("");
            for (var index = 0; index < after.Count; index++)
            {
                lines.Add($"{index + 1}. {after[index]}");
            }

            lines.Add("");
        }

        if (model.GitHub)
        {
            lines.Add("## Deploy from GitHub");
            lines.Add("");
            lines.Add("1. Put these files in an `infra` folder of your repository, and `.github/workflows/infrastructure.yml` at the repository root.");
            lines.Add("2. Run `./setup-github.ps1 -Repository <owner>/<name>` once. It lets GitHub sign in to Azure without passwords and saves the secrets and variables the workflow needs.");
            lines.Add($"3. In GitHub, open Settings > Environments > `{model.Settings.Environment}` and add yourself as a required reviewer, so every change waits for your approval.");
            lines.Add("4. Pull requests show the plan; merging to main applies it.");
            lines.Add("");
        }

        lines.AddRange(AppPipeline.ReadmeLines(model));
        lines.Add("## Delete everything");
        lines.Add("");
        lines.Add(model.Terraform
            ? $"`./deploy.ps1 -Destroy` asks you to type `{name}` and then deletes every resource and its data."
            : model.ExistingResourceGroup
                ? $"Delete the resources inside `{model.ResourceGroupName}` in the Azure portal; the group itself existed before and stays."
                : $"`az group delete --name {model.ResourceGroupName}` deletes every resource and its data.");
        if (model.Lock && !model.Terraform)
        {
            lines.Add($"First remove the delete lock: `az lock delete --name do-not-delete --resource-group {model.ResourceGroupName}`.");
        }

        if (model.Lock)
        {
            lines.Add("");
            lines.Add("The resource group has a delete lock so nobody deletes it by mistake; that is why deleting takes this extra step.");
        }

        lines.Add("");
        lines.Add("## Files");
        lines.Add("");
        lines.Add("| File | What it has |");
        lines.Add("| --- | --- |");
        foreach (var (file, text) in Files(model))
        {
            lines.Add($"| `{file}` | {text} |");
        }

        return string.Join('\n', lines) + "\n";
    }

    // AWS and Google Cloud.
    private static string Cloud(SketchModel model)
    {
        var aws = model.Platform == Platforms.Aws;
        var name = $"{model.Settings.Name}-{model.Settings.Environment}";
        var lines = new List<string>
        {
            $"# {model.Settings.Name} ({model.Settings.Environment}) on {model.Cloud.Label}",
            "",
            "Generated by Terraform Generator from your drawing (`sketch.json`). To change the design, open the drawing in Terraform Generator, change it, download again and replace these files (keep `backend.hcl` and `terraform.tfvars`).",
            "",
            "## What you need (once)",
            "",
            aws
                ? "- An AWS account where you can create these resources, and the AWS CLI (`winget install Amazon.AWSCLI`). Sign in with `aws configure sso` (or `aws configure` with an access key)."
                : $"- A Google Cloud project (`{model.GcpProject}`) with billing turned on, where you are Owner or Editor, and the Google Cloud CLI (`winget install Google.CloudSDK`).",
            "- PowerShell 7 (`winget install Microsoft.PowerShell`) and Terraform 1.10 or later (`winget install Hashicorp.Terraform`).",
            "",
            "`check-prereqs.ps1` checks all of this and signs you in." + (aws ? "" : " It also turns on the Google Cloud APIs the drawing uses."),
            "",
            "## Create or update everything",
            "",
            "Open PowerShell 7 in this folder and run:",
            "",
            "```powershell",
            "./deploy.ps1",
            "```",
            "",
            "It checks the tools, signs you in" + (model.RemoteState ? ", creates the bucket for the Terraform state (first time only)" : "")
                + ", shows the plan (what will be created, changed or deleted) and asks you to type `yes` before it changes anything. Run it again after every change.",
            "",
            model.RemoteState
                ? $"Terraform keeps a record of what it created (the *state*) in {(aws ? "an S3 bucket" : "a Cloud Storage bucket")} with versioning, which `bootstrap-state.ps1` creates. Never delete that bucket."
                : "Terraform keeps a record of what it created (the *state*) in `terraform.tfstate` in this folder. Do not lose it.",
            "",
        };

        if (!aws)
        {
            lines.Add("If Terraform says an API is not enabled, its message has a link that turns it on; or run `gcloud services enable <api name>` and deploy again.");
            lines.Add("");
        }

        var references = model.Generics.Any(resource => resource.Node.Props.Values.Any(value => value.StartsWith("ref:", StringComparison.Ordinal)));
        var smartFile = aws ? "aws.tf" : "gcp.tf";
        var smart = aws ? AwsGenerator.Any(model) : GcpGenerator.Any(model);
        var functions = model.OfKind(CloudKinds.Lambda).Concat(model.OfKind(CloudKinds.CloudFunction)).ToList();
        lines.Add("## How the boxes became code");
        lines.Add("");
        if (smart)
        {
            lines.Add($"The smart boxes are in `{smartFile}`, with what each one needs to work safely: " +
                (aws
                    ? "an IAM role per function and container, log groups, encryption, no public buckets, HTTPS only. Each arrow from code adds a statement to its role and the target's name as an environment variable."
                    : "a service account per service and function, encryption, no public buckets unless you chose a website. Each arrow from code gives its service account a role on the target and the target's name as an environment variable."));
            lines.Add("");
        }

        if (functions.Count > 0)
        {
            lines.Add($"Each function's code is its folder under `functions/` ({string.Join(", ", functions.Select(function => $"`functions/{function.Name}`"))}). " +
                "Terraform Generator puts a small starter there so the first deploy works: replace it with your code; Terraform zips the folder on every deploy. " +
                "Downloading again from Terraform Generator writes the starter again, so keep your code in your own repository.");
            lines.Add("");
        }

        if (model.Generics.Any())
        {
            lines.Add($"Each box from the full provider list is one Terraform resource in `resources.tf`, with the fields you filled in{(references ? "; a field that points to another box uses that box's value" : "")}.");
            lines.Add("");
        }

        lines.Add(aws ? "Every resource gets the tags in `variables.tf`." : "Every resource that takes labels gets the labels in `variables.tf`; the project and region come from the variables.");
        lines.Add("");
        if (model.GitHub)
        {
            lines.Add("## Deploy from GitHub");
            lines.Add("");
            lines.Add("1. Put these files in an `infra` folder of your repository, and `.github/workflows/infrastructure.yml` at the repository root.");
            lines.Add($"2. Run `./setup-github.ps1 -Repository <owner>/<name>` once. It lets GitHub sign in to {(aws ? "AWS" : "Google Cloud")} without passwords (OpenID Connect) and saves the variables the workflow needs.");
            lines.Add($"3. In GitHub, open Settings > Environments > `{model.Settings.Environment}` and add yourself as a required reviewer, so every change waits for your approval.");
            lines.Add("4. Pull requests show the plan; merging to main applies it.");
            lines.Add("");
        }

        lines.AddRange(AppPipeline.ReadmeLines(model));
        lines.Add("## Delete everything");
        lines.Add("");
        lines.Add($"`./deploy.ps1 -Destroy` asks you to type `{name}` and then deletes every resource and its data.");
        lines.Add("");
        lines.Add("## Files");
        lines.Add("");
        lines.Add("| File | What it has |");
        lines.Add("| --- | --- |");
        lines.Add("| `deploy.ps1` | Creates or updates everything, with a confirmation |");
        if (model.RemoteState)
        {
            lines.Add("| `bootstrap-state.ps1` | Creates the bucket for the Terraform state (once) |");
        }

        lines.Add("| `check-prereqs.ps1` | Checks the tools and the sign-in |");
        if (model.GitHub)
        {
            lines.Add("| `setup-github.ps1` | Lets GitHub Actions deploy without passwords (once) |");
            lines.Add("| `.github/workflows/infrastructure.yml` | The GitHub pipeline |");
        }

        lines.Add("| `versions.tf` | Terraform and provider versions" + (model.RemoteState ? ", state in the cloud" : "") + " |");
        lines.Add("| `main.tf` | The provider, with your region" + (aws ? " and default tags" : ", project and default labels") + " |");
        lines.Add("| `variables.tf` | Settings you can change without the drawing |");
        if (smart)
        {
            lines.Add($"| `{smartFile}` | The smart boxes and what each adds |");
        }

        if (functions.Count > 0)
        {
            lines.Add("| `functions/` | The code of each function (a starter to replace) |");
        }

        if (model.Generics.Any())
        {
            lines.Add("| `resources.tf` | Your boxes from the full provider list |");
        }

        lines.Add("| `outputs.tf` | The id of each resource, shown after a deploy |");
        lines.Add("| `.gitignore` | Keeps state, plans and your settings out of Git |");
        lines.Add("| `sketch.json` | Your drawing, to open again in Terraform Generator |");
        return string.Join('\n', lines) + "\n";
    }

    private static List<string> AfterFirstDeploy(SketchModel model)
    {
        var steps = new List<string>();
        var sql = model.Compute.SelectMany(app => model.Targets(app, Kinds.SqlDatabase).Select(database => (app, database))).ToList();
        if (sql.Count > 0)
        {
            var block = string.Join("\n", sql.Select(pair =>
                $"   -- In the database {pair.database.Name}, for {pair.app.Name} (output {pair.app.Label}_identity):\n" +
                "   CREATE USER [<identity>] FROM EXTERNAL PROVIDER;\n" +
                "   ALTER ROLE db_datareader ADD MEMBER [<identity>];\n" +
                "   ALTER ROLE db_datawriter ADD MEMBER [<identity>];"));
            steps.Add("Give each app access inside its SQL database. In the Azure portal open the database > Query editor, sign in with Microsoft Entra (you are its administrator) and run, with the identity name from the outputs:\n\n   ```sql\n" + block + "\n   ```\n");
        }

        var postgres = model.Compute.SelectMany(app => model.Targets(app, Kinds.Postgres).Select(server => (app, server))).ToList();
        if (postgres.Count > 0)
        {
            var block = string.Join("\n", postgres.Select(pair =>
                $"   -- On {pair.server.Name}, connected to the postgres database, for {pair.app.Name} (output {pair.app.Label}_identity):\n" +
                "   SELECT * FROM pgaadauth_create_principal('<identity>', false, false);\n" +
                $"   -- Then connected to the {pair.server.Label} database:\n" +
                "   GRANT ALL ON SCHEMA public TO \"<identity>\";"));
            steps.Add("Give each app access inside PostgreSQL. Connect as yourself (for example with `psql` and a token from `az account get-access-token --resource-type oss-rdbms`) and run:\n\n   ```sql\n" + block + "\n   ```\n");
        }

        foreach (var registry in model.Registries.Where(registry => model.ComputeSources(registry).Any()))
        {
            var images = model.ComputeSources(registry).Select(app => app.Kind == Kinds.ContainerApp ? app.P["image"] : app.P["dockerImage"]).Distinct();
            steps.Add($"Push your images to {registry.Name} before the apps can start: `az acr login --name <registry>` then `docker push <login server>/<image>` for {string.Join(", ", images.Select(image => $"`{image}`"))} (the login server is in the outputs).");
        }

        if (model.Zones.Any())
        {
            steps.Add("At the company where you bought each domain, set its name servers to the ones in the `_name_servers` outputs.");
        }

        if (model.FrontDoors.Any(frontDoor => model.Sources(frontDoor, Kinds.DnsZone).Any()))
        {
            steps.Add("Front Door checks each custom domain and issues its certificate by itself; this can take up to an hour after the name servers are set.");
        }

        if (model.NeedsNetwork)
        {
            steps.Add("Private resources can only be reached from the private network: to open one from your computer, use a VPN or a virtual machine in the network, or turn off Private only for a moment.");
        }

        if (model.Compute.Any() || model.StaticSites.Any())
        {
            steps.Add("Deploy your application code: the resources start empty (a placeholder page). Use your usual tool: `az webapp deploy`, `func azure functionapp publish`, `az containerapp update --image`, or the Static Web Apps GitHub action.");
        }

        return steps;
    }

    private static IEnumerable<(string File, string Text)> Files(SketchModel model)
    {
        if (model.Terraform)
        {
            yield return ("deploy.ps1", "Creates or updates everything, with a confirmation");
            if (model.RemoteState)
            {
                yield return ("bootstrap-state.ps1", "Creates the storage for the Terraform state (once)");
            }

            yield return ("versions.tf", "Terraform and provider versions" + (model.RemoteState ? ", state in Azure" : ""));
            yield return ("main.tf", "Provider, resource group, monitoring" + (model.Budget > 0 ? ", budget alert" : ""));
            yield return ("variables.tf", "Settings you can change without the drawing");
            if (model.NeedsNetwork)
            {
                yield return ("network.tf", "Private network, subnets and private DNS");
            }

            if (model.Compute.Any() || model.StaticSites.Any())
            {
                yield return ("apps.tf", "Plans and apps");
            }

            if (model.Resources.Any(resource => resource.Kind is Kinds.SqlDatabase or Kinds.Postgres or Kinds.CosmosDb or Kinds.Storage or Kinds.Redis or Kinds.ServiceBus or Kinds.ContainerRegistry))
            {
                yield return ("data.tf", "Databases, storage, cache, messaging, registry");
            }

            if (model.Vaults.Any() || model.Links.Any(link => Kinds.IsCompute(link.From.Kind) && !Kinds.IsCompute(link.To.Kind)))
            {
                yield return ("security.tf", "Key Vaults and what each app may use");
            }

            if (model.FrontDoors.Any() || model.Zones.Any())
            {
                yield return ("edge.tf", "Front Door and DNS");
            }

            if (TerraformGenerator.Logs(model) && TerraformGenerator.DiagnosticTargets(model).Any())
            {
                yield return ("monitoring.tf", "Logs and metrics of every resource");
            }

            yield return ("outputs.tf", "Addresses and names shown after a deploy");
            yield return ("terraform.tfvars.example", "Example of terraform.tfvars (deploy.ps1 writes the real one)");
        }

        if (model.Bicep)
        {
            yield return ("deploy-bicep.ps1", "Creates or updates everything with Bicep, with a preview and a confirmation");
            yield return ("bicep/main.bicep", "The same design in Bicep");
            yield return ("bicep/main.bicepparam", "Its parameters");
        }

        yield return ("check-prereqs.ps1", "Checks the tools and the Azure sign-in, registers the Azure services");
        if (model.GitHub)
        {
            yield return ("setup-github.ps1", "Lets GitHub Actions deploy without passwords (once)");
            yield return (".github/workflows/infrastructure.yml", "The GitHub pipeline");
        }

        yield return (".gitignore", "Keeps state, plans and your settings out of Git");
        yield return ("sketch.json", "Your drawing, to open again in Terraform Generator");
    }
}
